<script lang="ts">
import { onMount } from 'svelte'; let {texts=['Contabilidad inteligente','Control empresarial','Información clara'],interval=2600}: {texts?:string[];interval?:number}=$props();let index=$state(0);let node:HTMLSpanElement;
onMount(()=>{let stopped=false;const tick=()=>{if(stopped)return;const chars=[...node.querySelectorAll<HTMLElement>('.char')];chars.forEach((c,i)=>c.animate([{opacity:0,transform:'translateY(100%)'},{opacity:1,transform:'translateY(0)'}],{duration:480,delay:i*18,easing:'cubic-bezier(.22,1,.36,1)',fill:'forwards'}));setTimeout(()=>{if(stopped)return;chars.forEach((c,i)=>c.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(-120%)'}],{duration:360,delay:i*12,easing:'cubic-bezier(.77,0,.175,1)',fill:'forwards'}));setTimeout(()=>{if(!stopped){index=(index+1)%texts.length;tick()}},420)},interval-420)};tick();return()=>{stopped=true}});const chars=$derived([...texts[index]].map((char,i)=>({char,i})));
</script><span class="rotate" bind:this={node} aria-live="polite" aria-label={texts[index]}>{#each chars as item}<span class="char" aria-hidden="true">{item.char===' '?'\u00a0':item.char}</span>{/each}</span><style>.rotate{display:inline-flex;overflow:hidden;vertical-align:bottom;min-height:1.05em}.char{display:inline-block;opacity:0;transform:translateY(100%);white-space:pre}</style>